string current="";try{var data=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText(@"C:\Users\Stormtrooper\Git\EVOLVE - Frame\output\revit\floor_web_manifest.json"));var existing=new FilteredElementCollector(document).OfClass(typeof(DirectShape)).Cast<DirectShape>().Where(s=>s.ApplicationId=="EVOLVE.Leichhardt").Select(s=>s.ApplicationDataId).ToHashSet();int count=0;
using(var tx=new Transaction(document,"MultiStrut steel web geometry")){tx.Start();var mat=new FilteredElementCollector(document).OfClass(typeof(Material)).Cast<Material>().FirstOrDefault(m=>m.Name=="LC MultiStrut - G300 Z275 1mm");if(mat==null){mat=(Material)document.GetElement(Material.Create(document,"LC MultiStrut - G300 Z275 1mm"));mat.Color=new Color(159,164,169);mat.MaterialClass="Metal";}
var cat=new ElementId(BuiltInCategory.OST_StructuralFraming);if(!DirectShape.IsValidCategoryId(cat,document))cat=new ElementId(BuiltInCategory.OST_GenericModel);
foreach(var row in data.Where(r=>!existing.Contains((string)r["mark"])).Take(300)){current=(string)row["mark"];var pts=row["points"].Select(p=>new XYZ((double)p[0]/304.8,(double)p[1]/304.8,(double)p[2]/304.8)).ToArray();var loop=new CurveLoop();for(int i=0;i<pts.Length;i++)loop.Append(Line.CreateBound(pts[i],pts[(i+1)%pts.Length]));var solid=GeometryCreationUtilities.CreateExtrusionGeometry(new List<CurveLoop>{loop},XYZ.BasisX,1/304.8,new SolidOptions(mat.Id,ElementId.InvalidElementId));var shape=DirectShape.CreateElement(document,cat);shape.SetShape(new List<GeometryObject>{solid});shape.Name=(string)row["mark"];shape.ApplicationId="EVOLVE.Leichhardt";shape.ApplicationDataId=(string)row["mark"];shape.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.Set((string)row["mark"]);shape.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set((string)row["source"]);count++;}tx.Commit();}
document.Save();return new{created=count,total=data.Count,warnings=document.GetWarnings().Select(w=>w.GetDescriptionText()).ToArray()};}catch(Exception ex){return new{current,failure=ex.ToString()};}

